<?php
namespace App\Services; use App\Core\{Application,Session,Response};
final class AuthService{public function __construct(private Application $app){} public function user():?array{$id=Session::get('user_id'); if(!$id)return null; $s=$this->app->db()->pdo()->prepare('SELECT * FROM users WHERE id=? AND status="active"');$s->execute([$id]);return $s->fetch()?:null;} public function attempt(string $login,string $pass):bool{$pdo=$this->app->db()->pdo();$s=$pdo->prepare('SELECT * FROM users WHERE (username=? OR email=?) AND status="active"');$s->execute([$login,$login]);$u=$s->fetch(); if($u&&password_verify($pass,$u['password_hash'])){Session::regenerate();Session::put('user_id',$u['id']);$pdo->prepare('INSERT INTO login_logs(user_id,ip,user_agent,created_at) VALUES(?,?,?,NOW())')->execute([$u['id'],$_SERVER['REMOTE_ADDR']??'',$_SERVER['HTTP_USER_AGENT']??'']);return true;} $pdo->prepare('INSERT INTO failed_logins(login,ip,user_agent,created_at) VALUES(?,?,?,NOW())')->execute([$login,$_SERVER['REMOTE_ADDR']??'',$_SERVER['HTTP_USER_AGENT']??'']);return false;} public function require():array{$u=$this->user(); if(!$u) Response::redirect('/'.$this->app->config()->get('admin_path').'/login'); return $u;} public function logout():void{Session::destroy();}}
